export const ORDER_STATUS={draft:'Черновик',assigned:'Назначено',in_progress:'В работе',paused:'Приостановлено',review:'На проверке',completed:'Завершено',cancelled:'Отменено'};
export const ORDER_NEXT={draft:['assigned','cancelled'],assigned:['draft','in_progress','cancelled'],in_progress:['paused','review'],paused:['in_progress','review','cancelled'],review:['in_progress','completed'],completed:[],cancelled:[]};
export function orderTransitionBlocker(o,status){
 const rows=o.service_order_items||[];
 if(status==='in_progress'&&o.jobs?.status==='open')return 'Сначала подготовь заявку: переведи её в «Запланирована» или «В работе».';
 if(status==='in_progress'&&['done','cancelled'].includes(o.jobs?.status))return 'Исходная заявка завершена или отменена.';
 if(['assigned','in_progress'].includes(status)&&(!o.lead_engineer||!(o.engineer_ids||[]).length||!o.date_from||!o.date_to||!rows.length))return 'Для назначения и начала работы нужны команда, ответственный инженер, период и состав задания.';
 if(['review','completed'].includes(status)&&!rows.length)return 'Сначала добавь работы или материалы в состав задания.';
 if(status==='completed'&&rows.some(i=>Number(i.done_qty||0)+Number(i.transferred_qty||0)<Number(i.planned_qty)))return 'Есть невыполненный остаток: внеси результат или перенеси остаток.';
 if(['completed','cancelled'].includes(status)&&(o.trip_service_orders||[]).some(x=>x.trips&&!x.trips.deleted_at&&!['done','cancelled'].includes(x.trips.status)))return 'Сначала заверши или отмени связанные выезды.';
 return '';
}
export const remainingQty=i=>i.request_finance_void_event_id?0:Math.max(0,Number(i.planned_qty)-Number(i.done_qty||0)-Number(i.transferred_qty||0));
export const visibleTripCount=o=>(o?.trip_service_orders||[]).filter(x=>x?.trips&&!x.trips.deleted_at).length;
const isFinanceVoided=i=>!!(i?.request_finance_void_event_id||i?.legacy_snapshot?.request_finance_voided_at);
export function materialTotals(items=[],status=''){return items.filter(i=>!isFinanceVoided(i)&&i.kind==='material').reduce((a,i)=>{const price=Number(i.unit_price_snapshot||0),cost=Number(i.unit_cost_snapshot||0),billable=i.billable!==false,planned=status==='cancelled'?Number(i.done_qty||0):Math.max(0,Number(i.planned_qty||0)-Number(i.transferred_qty||0));a.planRevenue+=billable?planned*price:0;a.planCost+=planned*cost;a.factRevenue+=billable?Number(i.done_qty||0)*price:0;a.factCost+=Number(i.done_qty||0)*cost;return a;},{planRevenue:0,planCost:0,factRevenue:0,factCost:0});}
export function workTotals(items=[],status=''){return items.filter(i=>!isFinanceVoided(i)&&i.kind!=='material').reduce((a,i)=>{const revenue=i.financial_revenue_snapshot,cost=i.financial_cost_snapshot,plannedQty=Number(i.planned_qty||0),doneQty=Number(i.done_qty||0),planQty=status==='cancelled'?doneQty:Math.max(0,plannedQty-Number(i.transferred_qty||0));if(revenue==null||cost==null||!Number.isFinite(Number(revenue))||!Number.isFinite(Number(cost))||plannedQty<=0){a.unpriced+=1;return a;}const revenueRate=Number(revenue)/plannedQty,costRate=Number(cost)/plannedQty;a.planRevenue+=planQty*revenueRate;a.planCost+=planQty*costRate;a.factRevenue+=doneQty*revenueRate;a.factCost+=doneQty*costRate;return a;},{planRevenue:0,planCost:0,factRevenue:0,factCost:0,unpriced:0});}
export function nextOrderStates(status,manager){return (ORDER_NEXT[status]||[]).filter(s=>manager||(['assigned','paused'].includes(status)&&s==='in_progress')||(status==='in_progress'&&['paused','review'].includes(s)));}
