export function orderProgress(list=[]){
 const active=list.filter(i=>!isFinanceVoided(i)),works=active.filter(i=>i.kind!=='material'&&Number(i.planned_qty)>0),materials=active.filter(i=>i.kind==='material');
 const done=works.filter(i=>Number(i.done_qty||0)>=Number(i.planned_qty)).length,partial=works.filter(i=>Number(i.done_qty||0)>0&&Number(i.done_qty)<Number(i.planned_qty)).length,carried=works.filter(i=>Number(i.transferred_qty||0)>0).length;
 return (works.length?`${done} из ${works.length} работ выполнено${partial?' · частично '+partial:''}${carried?' · остаток перенесён по '+carried+' работам':''}`:'Работы не добавлены')+(materials.length?` · материалов использовано ${materials.filter(i=>Number(i.done_qty||0)>0).length} из ${materials.length}`:'');
}
