 async function requestPanel(id){const box=$('jobOrders');if(!box)return;box.hidden=!id;if(!id)return;try{await load();const tasks=orders.filter(o=>belongs(o,id));let summary='';if(tasks.length&&ctx.tripCostSummary){try{const rows=(await Promise.all(tasks.map(o=>ctx.tripCostSummary(o.id)))).flat();const totals=rows.reduce((a,x)=>({km:a.km+Number(x.distance_km||0),distance:a.distance+Number(x.distance_cost||0),hours:a.hours+Number(x.labor_hours||0),labor:a.labor+Number(x.labor_cost||0)}),{km:0,distance:0,hours:0,labor:0});if(rows.length)summary=`<div class="order-trip-cost-summary"><b>Выездные затраты заданий · ${num(totals.distance+totals.labor)} ₴</b><span>${num(totals.km)} км · ${num(totals.distance)} ₴</span><span>${num(totals.hours)} чел.-ч · ${num(totals.labor)} ₴</span><small>Учитываются только подтверждённые доли. Нераспределённый остаток и затраты материалов показаны отдельно.</small></div>`;}catch(e){summary=`<p class="hint">Сводка выездных затрат временно недоступна: ${esc(e.message)}</p>`;}}const additional=tasks.filter(o=>o.seed_request_id!==id),totals=additional.map(o=>({w:workTotals(o.service_order_items,o.status),m:materialTotals(o.service_order_items,o.status)})).reduce((a,x)=>({plan:a.plan+x.w.planRevenue+x.m.planRevenue,fact:a.fact+x.w.factRevenue+x.m.factRevenue}),{plan:0,fact:0});box.innerHTML=childHtml(id,true)+(manager()&&additional.length?'<p class="hint">Дополнительные задания: '+additional.length+' · план '+num(totals.plan)+' ₴ · факт '+num(totals.fact)+' ₴. Эти суммы не включены в базовую смету заявки.</p>':'')+summary;wireChildren(box);box.querySelectorAll('[data-order-scope],[data-order-new]').forEach(b=>b.hidden=true);}catch(e){box.textContent='Не удалось загрузить задания: '+e.message;}}
