 function storeResultDraft(){if(!current?.id||loadedUser!==ctx.userId()||!reportAllowed(current))return;try{storage().setItem(draftKey(current),JSON.stringify({revision:resultExpected??current.revision,values:resultValues(),attempt:resultAttempt}));}catch{/* A blocked browser store must not discard the mounted form. */}}
